// A function approaching height L at x=a from both sides, but with a hole
// (removable point) at x=a. We use a smooth curve that passes through (a, L).
function f(x){ return L + 0.6 * (x - a) + 0.25 * (x - a) * (x - a); }
v.fn(x => (Math.abs(x - a) < 0.04 ? NaN : f(x)), { color: H.colors.accent, width: 3 });
